using Respira.ServiceDefaults.Contracts.CQRS;

namespace Respira.Saga.Application.Features.Delete.Commands
{
    /// <summary>
    /// Local (never sent over the broker) message produced by the profile deletion
    /// endpoint that starts the delete saga. The three identifiers come from the caller,
    /// since this service owns no database to look them up in.
    /// </summary>
    public record StartDeleteCommand : ICommand
    {
        /// <summary>Identifier generated by the endpoint; becomes the saga id.</summary>
        public Guid SagaId { get; set; }

        /// <summary>Account to soft delete.</summary>
        public Guid AccountId { get; set; }

        /// <summary>Doctor/manager profile to soft delete.</summary>
        public Guid DoctorId { get; set; }

        /// <summary>Media asset of the avatar to delete; empty when there is none.</summary>
        public Guid MediaId { get; set; }
    }
}
